from collections import deque, defaultdict
import heapq
class StatisticsTracker:
    def __init__(self):
        self.q = deque()
        self.cnt = defaultdict(int)
        self.total = 0
        self.ids = {}
        self.bit = [0]
        self.heap = []
    def _upd(self, i, d):
        while len(self.bit) <= i:
            self.bit.append(0)
        while i < len(self.bit):
            self.bit[i] += d
            i += i & (-i)
    def _kth(self, k):
        i, rem = 0, k
        pw = 1 << (len(self.bit) - 1).bit_length()
        while pw:
            ni = i + pw
            if ni < len(self.bit) and self.bit[ni] < rem:
                i, rem = ni, rem - self.bit[ni]
            pw >>= 1
        return i + 1
    def addNumber(self, number: int) -> None:
        self.q.append(number)
        self.cnt[number] += 1
        self.total += number
        if number not in self.ids:
            self.ids[number] = len(self.ids) + 1
        self._upd(self.ids[number], 1)
        heapq.heappush(self.heap, (-self.cnt[number], number))
    def removeFirstAddedNumber(self) -> None:
        x = self.q.popleft()
        self.cnt[x] -= 1
        self.total -= x
        self._upd(self.ids[x], -1)
        if self.cnt[x] > 0:
            heapq.heappush(self.heap, (-self.cnt[x], x))
    def getMean(self) -> int:
        return self.total // len(self.q)
    def getMedian(self) -> int:
        return self._kth(len(self.q) // 2 + 1)
    def getMode(self) -> int:
        while self.cnt[self.heap[0][1]] != -self.heap[0][0]:
            heapq.heappop(self.heap)
        return self.heap[0][1]

