class StatisticsTracker {
    queue<int> q;
    unordered_map<int,int> cnt, ids;
    long long total = 0;
    vector<int> bit;
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    void upd(int i, int d) {
        while ((int)bit.size() <= i) bit.push_back(0);
        for (; i < (int)bit.size(); i += i & (-i)) bit[i] += d;
    }
    int kth(long long k) {
        int i = 0, pw = 1;
        long long rem = k;
        while ((pw << 1) < (int)bit.size()) pw <<= 1;
        for (; pw; pw >>= 1) {
            int ni = i + pw;
            if (ni < (int)bit.size() && bit[ni] < rem) { i = ni; rem -= bit[ni]; }
        }
        return i + 1;
    }
public:
    StatisticsTracker() { bit.push_back(0); }
    void addNumber(int x) {
        q.push(x);
        if (!ids.count(x)) ids[x] = ids.size() + 1;
        cnt[x]++; total += x;
        upd(ids[x], 1);
        pq.push({-cnt[x], x});
    }
    void removeFirstAddedNumber() {
        int x = q.front(); q.pop();
        cnt[x]--; total -= x;
        upd(ids[x], -1);
        if (cnt[x] > 0) pq.push({-cnt[x], x});
    }
    int getMean() { return (int)(total / q.size()); }
    int getMedian() { return kth(q.size() / 2 + 1); }
    int getMode() {
        while (cnt[pq.top().second] != -pq.top().first) pq.pop();
        return pq.top().second;
    }
};

