import java.util.*;
class StatisticsTracker {
    private ArrayDeque<Integer> q = new ArrayDeque<>();
    private Map<Integer,Integer> cnt = new HashMap<>(), ids = new HashMap<>();
    private long total = 0;
    private int[] bit = new int[1];
    private PriorityQueue<int[]> pq = new PriorityQueue<>(
        (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
    private void upd(int i, int d) {
        while (bit.length <= i) bit = Arrays.copyOf(bit, bit.length * 2);
        for (; i < bit.length; i += i & (-i)) bit[i] += d;
    }
    private int kth(long k) {
        int i = 0, pw = Integer.highestOneBit(Math.max(bit.length - 1, 1));
        long rem = k;
        for (; pw > 0; pw >>= 1) {
            int ni = i + pw;
            if (ni < bit.length && bit[ni] < rem) { i = ni; rem -= bit[ni]; }
        }
        return i + 1;
    }
    public StatisticsTracker() {}
    public void addNumber(int x) {
        q.addLast(x);
        ids.putIfAbsent(x, ids.size() + 1);
        cnt.merge(x, 1, Integer::sum);
        total += x;
        upd(ids.get(x), 1);
        pq.add(new int[]{-cnt.get(x), x});
    }
    public void removeFirstAddedNumber() {
        int x = q.pollFirst();
        cnt.merge(x, -1, Integer::sum);
        total -= x;
        upd(ids.get(x), -1);
        if (cnt.get(x) > 0) pq.add(new int[]{-cnt.get(x), x});
    }
    public int getMean() { return (int)(total / q.size()); }
    public int getMedian() { return kth(q.size() / 2 + 1); }
    public int getMode() {
        while (cnt.get(pq.peek()[1]) != -pq.peek()[0]) pq.poll();
        return pq.peek()[1];
    }
}

