function Heap() { this.a = []; }
Heap.prototype.less = function(i, j) {
    return this.a[i][0] < this.a[j][0] || (this.a[i][0] === this.a[j][0] && this.a[i][1] < this.a[j][1]);
};
Heap.prototype.push = function(x) {
    const a = this.a; a.push(x); let i = a.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (this.less(i, p)) { [a[i], a[p]] = [a[p], a[i]]; i = p; } else break; }
};
Heap.prototype.pop = function() {
    const a = this.a, t = a[0], l = a.pop();
    if (a.length) { a[0] = l; let i = 0;
        for (;;) { let c = 2*i+1; if (c >= a.length) break;
            if (c+1 < a.length && this.less(c+1, c)) c++;
            if (this.less(c, i)) { [a[i], a[c]] = [a[c], a[i]]; i = c; } else break; } }
    return t;
};
Heap.prototype.top = function() { return this.a[0]; };
var StatisticsTracker = function() {
    this.q = []; this.head = 0; this.cnt = new Map(); this.ids = new Map();
    this.total = 0; this.bit = [0]; this.pq = new Heap();
};
StatisticsTracker.prototype.upd = function(i, d) {
    const b = this.bit;
    while (b.length <= i) b.push(0);
    for (; i < b.length; i += i & (-i)) b[i] += d;
};
StatisticsTracker.prototype.kth = function(k) {
    let i = 0, rem = k, pw = 1;
    while ((pw << 1) < this.bit.length) pw <<= 1;
    for (; pw > 0; pw >>= 1) {
        const ni = i + pw;
        if (ni < this.bit.length && this.bit[ni] < rem) { i = ni; rem -= this.bit[ni]; }
    }
    return i + 1;
};
StatisticsTracker.prototype.addNumber = function(x) {
    this.q.push(x);
    if (!this.ids.has(x)) this.ids.set(x, this.ids.size + 1);
    this.cnt.set(x, (this.cnt.get(x) || 0) + 1);
    this.total += x;
    this.upd(this.ids.get(x), 1);
    this.pq.push([-this.cnt.get(x), x]);
};
StatisticsTracker.prototype.removeFirstAddedNumber = function() {
    const x = this.q[this.head++];
    this.cnt.set(x, this.cnt.get(x) - 1);
    this.total -= x;
    this.upd(this.ids.get(x), -1);
    if (this.cnt.get(x) > 0) this.pq.push([-this.cnt.get(x), x]);
};
StatisticsTracker.prototype.getMean = function() {
    return Math.floor(this.total / (this.q.length - this.head));
};
StatisticsTracker.prototype.getMedian = function() {
    return this.kth(((this.q.length - this.head) >> 1) + 1);
};
StatisticsTracker.prototype.getMode = function() {
    while (this.cnt.get(this.pq.top()[1]) !== -this.pq.top()[0]) this.pq.pop();
    return this.pq.top()[1];
};
